const {
    ipcRenderer,
} = require('electron');

const logger = require('electron-log');
const console = logger;

const FileWriter = require("./fileWriter/fileWriter")
const MultiFileWriter = require("./fileWriter/multiFileWriter");

function uploadFile(id) {
    console.log('[Recorder] Triggering upload for ID:', id);
    ipcRenderer.send('_uploadFile', id);
}

class Recorder {

    /**
     * @type {MediaStream}
     */
    #stream
    
    #onRecordHandler
    
    /**
     * @type {{maxVideoLengthInSec: number, checkLengthInSec: number, path: string}}
     */
    #config
    
    /**
     * @type {MediaRecorder}
     */
    #mediaRecorder

    /**
     * @type {number | undefined}
     */
    #currentStreamStart

    /**
     * @type {FileWriter}
     */
    #fileWriter

    /**
     * @type {boolean}
     */
    #recordingStopped

    /**
     * 
     * @param {MediaStream} stream 
     * @param {{maxVideoLengthInSec: number, checkLengthInSec: number, path: string, bitRate: number, uploadId: number, startedAt: number}} config
     * @param {() => void} onRecordHandler
     */
    constructor(stream, config, onRecordHandler) {
        console.log('[Recorder] Constructor called');
        console.log('[Recorder] Config:', {
            path: config.path,
            uploadId: config.uploadId,
            bitRate: config.bitRate,
            checkLengthInSec: config.checkLengthInSec,
            maxVideoLengthInSec: config.maxVideoLengthInSec,
            startedAt: new Date(config.startedAt).toISOString()
        });

        this.#stream = stream
        this.#onRecordHandler = onRecordHandler,
        this.#config = config;

        // Check if audio track is available
        const hasAudio = this.#stream.getAudioTracks().length > 0;
        const hasVideo = this.#stream.getVideoTracks().length > 0;
        console.log('[Recorder] Stream composition:', {
            hasVideo,
            hasAudio,
            videoTracks: this.#stream.getVideoTracks().length,
            audioTracks: this.#stream.getAudioTracks().length
        });

        if (!hasVideo) {
            throw new Error('No video track available in stream!');
        }

        // Build recorder options dynamically based on available tracks
        const recorderOptions = {
            mimeType: 'video/mp4;codecs=avc1.64003E,mp4a.40.2',
            videoBitsPerSecond: config.bitRate,
        };

        // Only add audioBitsPerSecond if audio track exists
        if (hasAudio) {
            recorderOptions.audioBitsPerSecond = config.bitRate;
        }

        console.log('[Recorder] MediaRecorder options:', recorderOptions);

        this.#mediaRecorder = new MediaRecorder(this.#stream, recorderOptions);
        this.#mediaRecorder.ondataavailable = this.#handleStream.bind(this);
        this.#mediaRecorder.start(config.checkLengthInSec * 1000);
        this.#currentStreamStart = Date.now();

        console.log('[Recorder] MediaRecorder started');
        console.log('[Recorder] Recording will auto-stop at:', new Date(this.#currentStreamStart + config.maxVideoLengthInSec * 1000).toISOString());
        console.log('[Recorder] Data available events every:', config.checkLengthInSec, 'seconds');

        const multiFileWriter = new MultiFileWriter(this.#config.path, () => {
            console.log('[Recorder] File writing completed, triggering upload');
            uploadFile(config.uploadId);
        });

        multiFileWriter.addFileWriter(FileWriter, [config.path, {
            startTime: config.startedAt,
        }]);

        this.#fileWriter = multiFileWriter;
        this.#recordingStopped = false;

        console.log('[Recorder] Recorder initialized successfully');
    }

    async #stop() {
        try {
            console.log('[Recorder] #stop called');
            this.#recordingStopped = true;

            await new Promise((resolve, reject) => {
                console.log('[Recorder] Stopping MediaRecorder...');
                this.#mediaRecorder.onstop = (ev) => {
                    console.log('[Recorder] MediaRecorder stopped successfully');
                    resolve();
                }
                this.#mediaRecorder.stop();
            });

            console.log('[Recorder] Signaling file writer to complete');
            this.#fileWriter.setWriteComplete();
            console.log('[Recorder] Stop sequence completed');
        } catch (error) {
            console.error('[Recorder] Error during stop:', error);
        }
    }

    /**
     *
     * @param {BlobEvent} event
     */
    #handleStream(event) {
        const now = Date.now();
        const stopTime = this.#currentStreamStart + this.#config.maxVideoLengthInSec * 1000;
        const elapsed = (now - this.#currentStreamStart) / 1000;
        const remaining = (stopTime - now) / 1000;

        console.log('[Recorder] ondataavailable event');
        console.log('[Recorder] Blob size:', event.data.size, 'bytes');
        console.log('[Recorder] Elapsed:', elapsed.toFixed(1), 'seconds');
        console.log('[Recorder] Remaining:', remaining.toFixed(1), 'seconds');

        if (event.data.size == 0) {
            console.warn('[Recorder] Received empty blob, skipping');
            return;
        }

        const blob = new Blob([event.data], {
            type: 'video/mp4;codecs=avc1.64003E,mp4a.40.2'
        });

        console.log('[Recorder] Writing blob to file writer');
        this.#fileWriter.write(blob);

        // Check if we've reached the maximum recording time
        if (stopTime < now) {
            if (!this.#recordingStopped) {
                console.log('[Recorder] Maximum recording time reached, stopping');
                console.log('[Recorder] Stop time:', new Date(stopTime).toISOString());
                console.log('[Recorder] Current time:', new Date(now).toISOString());

                this.#stop();
                this.#onRecordHandler();
                console.log('[Recorder] onRecordHandler callback invoked');
            }
        }
    }

    /**
     *
     * @param {boolean | undefined} lazy
     * @returns
     */
    async stopRecording(lazy) {
        console.log('[Recorder] stopRecording called, lazy:', lazy);

        await this.#stop();

        if (!lazy) {
            console.log('[Recorder] Writing all remaining chunks (non-lazy stop)');
            await this.#fileWriter.writeAllChunks();
            console.log('[Recorder] All chunks written, recording fully stopped');
            return;
        } else {
            console.log('[Recorder] Lazy stop - chunks will be written in background');
        }
    }

}


module.exports = Recorder;
