const {
    ipcRenderer,
} = require('electron');

const dayjs = require('dayjs');

const logger = require('electron-log');
const Recorder = require('./singleRecord');
const fs = require('fs');
const path = require('path');
console = logger


const uploadTimeBufferInSecond = 2 * 60;

class RecorderManager {
    #devices
    /**
     * @type {MediaStream}
     */
    #stream
    /**
     * @type {MediaStream}
     */


    /**
     * @type {string}
     */
    #basePath

    /**
     * @type {{maxVideoLengthInSec: number, checkLengthInSec: number}}
     */
    #config

    /**
     * @type {string}
     */
    #quizId

    /**
     * @type {string}
     */
    #userId


    /**
     * @type {Recorder}
     */
    #recorder

    /**
     * @type {NodeJS.Timeout | undefined}
     */
    #streamHealthInterval

    /**
     * 
     * @param {string} deviceToRecord 
     * @param {string} quizId 
     * @param {string} userId 
     * @param {{ maxVideoLengthInSec: number, checkLengthInSec: number }} config 
     */
    constructor(deviceToRecord, quizId, userId, config) {
        // this.#devices = ipcRenderer.sendSync('listDevices');
        // this.#fileWriteStream = null;
        this.#quizId = quizId,
        this.#userId = userId,
        this.#config = config;
        try {
            const directoryPath = ipcRenderer.sendSync('_getRecordingPath', quizId, userId);
            this.#basePath = directoryPath;
            const isDirectoryPresent = fs.existsSync(directoryPath);
            if (!isDirectoryPresent) {
                fs.mkdirSync(directoryPath);
            }
        } catch (error) {
            console.log(error);
        }
    }

    createNewFileStream() {
        const filePath = `${Date.now()}`;
        const streamPath = path.join(this.#basePath, filePath);
        const fullPath = `${streamPath}.mp4`;

        console.log('[RecordHandler] Creating new file stream');
        console.log('[RecordHandler] Quiz ID:', this.#quizId);
        console.log('[RecordHandler] User ID:', this.#userId);
        console.log('[RecordHandler] File path:', fullPath);
        console.log('[RecordHandler] Max video length:', this.#config.maxVideoLengthInSec, 'seconds');
        console.log('[RecordHandler] Check length interval:', this.#config.checkLengthInSec, 'seconds');

        const uploadId = ipcRenderer.sendSync('_getUploadId', {
            quizId: this.#quizId,
            userId: this.#userId,
            path: fullPath,
            weightTime: dayjs().add(this.#config.maxVideoLengthInSec + uploadTimeBufferInSecond, 'second').toDate().getTime(),
        });

        if (uploadId.error) {
            console.error('[RecordHandler] Failed to get upload ID:', uploadId.error);
            throw new Error(`Failed to get upload ID: ${uploadId.error}`);
        }

        console.log('[RecordHandler] Upload ID obtained:', uploadId);

        this.#recorder = new Recorder(this.#stream, {
            path: fullPath,
            checkLengthInSec: this.#config.checkLengthInSec,
            maxVideoLengthInSec: this.#config.maxVideoLengthInSec,
            startedAt: Date.now(),
            uploadId: uploadId,
            bitRate: 100000,
        }, this.changeRecorder.bind(this));

        console.log('[RecordHandler] Recorder instance created successfully');
    }
    
    /**
     *
     * @param {MediaStream} stream
     */
    async startRecording(stream) {
        console.log('[RecordHandler] startRecording called');

        if (this.#stream) {
            console.warn('[RecordHandler] Stream is already active, skipping');
            return;
        }

        if (!stream) {
            console.log('[RecordHandler] No stream provided, requesting camera access');
            stream = await this.#getMediaStream();
        } else {
            console.log('[RecordHandler] Using provided stream');
        }

        this.#stream = stream;

        const videoTracks = stream.getVideoTracks();
        const audioTracks = stream.getAudioTracks();
        console.log('[RecordHandler] Stream tracks:', {
            video: videoTracks.length,
            audio: audioTracks.length,
            videoSettings: videoTracks[0]?.getSettings(),
            audioSettings: audioTracks[0]?.getSettings()
        });

        this.#addStreamHealthMonitoring();
        this.createNewFileStream();
        console.log('[RecordHandler] Recording started successfully');
    }

    /**
     * Attempts to get media stream with graceful audio fallback
     * @returns {Promise<MediaStream>}
     */
    async #getMediaStream() {
        const videoConstraints = {
            width: 640,
            height: 480,
            frameRate: 15,
        };

        // Attempt 1: Try with audio
        try {
            console.log('Attempting to get video + audio stream');
            const stream = await navigator.mediaDevices.getUserMedia({
                audio: true,
                video: videoConstraints
            });
            console.log('Successfully obtained video + audio stream');
            return stream;
        } catch (error) {
            console.warn('Failed to get audio track:', error.name, error.message);

            // If audio failed, try video-only
            if (error.name === 'NotFoundError' ||
                error.name === 'NotReadableError' ||
                error.name === 'OverconstrainedError') {
                try {
                    console.log('Attempting video-only stream');
                    const stream = await navigator.mediaDevices.getUserMedia({
                        audio: false,
                        video: videoConstraints
                    });
                    console.log('Successfully obtained video-only stream');
                    return stream;
                } catch (videoError) {
                    console.error('Failed to get video stream:', videoError.name, videoError.message);
                    throw this.#createUserFriendlyError(videoError);
                }
            }

            // For other errors (like NotAllowedError), throw immediately
            console.error('Camera access error:', error.name, error.message);
            throw this.#createUserFriendlyError(error);
        }
    }

    /**
     * Creates user-friendly error messages
     * @param {Error} error
     * @returns {Error}
     */
    #createUserFriendlyError(error) {
        const friendlyError = new Error();

        switch (error.name) {
            case 'NotAllowedError':
                friendlyError.message = 'Camera permission denied. Please allow camera access to continue with the exam.';
                friendlyError.userAction = 'ALLOW_CAMERA';
                break;
            case 'NotFoundError':
                friendlyError.message = 'No camera device found. Please connect a camera to continue with the exam.';
                friendlyError.userAction = 'CONNECT_CAMERA';
                break;
            case 'NotReadableError':
                friendlyError.message = 'Camera is already in use by another application. Please close other apps using the camera.';
                friendlyError.userAction = 'CLOSE_OTHER_APPS';
                break;
            case 'OverconstrainedError':
                friendlyError.message = 'Camera does not support required settings. Please use a different camera.';
                friendlyError.userAction = 'USE_DIFFERENT_CAMERA';
                break;
            case 'AbortError':
                friendlyError.message = 'Camera access was aborted. Please try again.';
                friendlyError.userAction = 'RETRY';
                break;
            default:
                friendlyError.message = `Camera error: ${error.message}. Please check your camera and try again.`;
                friendlyError.userAction = 'RETRY';
        }

        friendlyError.originalError = error;
        return friendlyError;
    }

    /**
     * Monitors stream health and detects disconnections
     */
    #addStreamHealthMonitoring() {
        if (!this.#stream) return;

        const videoTrack = this.#stream.getVideoTracks()[0];
        const audioTracks = this.#stream.getAudioTracks();

        if (videoTrack) {
            videoTrack.onended = () => {
                console.error('Video track ended unexpectedly - camera disconnected!');
                this.#handleCameraDisconnect();
            };

            videoTrack.onmute = () => {
                console.warn('Video track muted');
            };

            videoTrack.onunmute = () => {
                console.log('Video track unmuted');
            };
        }

        if (audioTracks.length > 0) {
            audioTracks[0].onended = () => {
                console.warn('Audio track ended - microphone disconnected (continuing video-only)');
            };
        }

        // Check stream health periodically
        this.#streamHealthInterval = setInterval(() => {
            if (!this.#stream || !this.#stream.active) {
                console.error('Stream became inactive!');
                this.#handleCameraDisconnect();
            }
        }, 5000); // Check every 5 seconds
    }

    /**
     * Handles camera disconnection during recording
     */
    #handleCameraDisconnect() {
        if (this.#streamHealthInterval) {
            clearInterval(this.#streamHealthInterval);
        }

        // Stop current recording
        if (this.#recorder) {
            this.#recorder.stopRecording(true); // lazy stop
        }

        console.error('Camera disconnected during exam. Recording stopped.');

        // Notify main process about camera disconnect
        ipcRenderer.send('cameraDisconnected', {
            quizId: this.#quizId,
            userId: this.#userId,
            timestamp: Date.now()
        });
    }

    stopRecording() {
        console.log('[RecordHandler] stopRecording called');

        // Clear health monitoring interval
        if (this.#streamHealthInterval) {
            clearInterval(this.#streamHealthInterval);
            this.#streamHealthInterval = undefined;
            console.log('[RecordHandler] Health monitoring interval cleared');
        }

        // Stop all tracks in the stream
        if (this.#stream) {
            const tracks = this.#stream.getTracks();
            console.log('[RecordHandler] Stopping', tracks.length, 'media tracks');
            tracks.forEach(track => {
                console.log('[RecordHandler] Stopping track:', track.kind, track.label);
                track.stop();
            });
        }

        console.log('[RecordHandler] Calling recorder.stopRecording()');
        return this.#recorder?.stopRecording();
    }

    async changeRecorder() {
        console.log('[RecordHandler] changeRecorder called - creating new recording segment');
        console.log('[RecordHandler] Previous recorder will be stopped and new one created');
        this.createNewFileStream();
    }
}


module.exports = RecorderManager;