const AbstractFileWriter = require('./index');
const logger = require('electron-log');
const console = logger;

class MultiFileWriter {

    /**
     * @type {Array<AbstractFileWriter>}
     */
    #fileWriter = []

    /**
     * @type {(string) => void}
     */
    #callback

    /**
     * @type {string}
     */
    #filePath

    /**
     *
     * @param {onCompletion?: (string) => void} onCompletion
     */
    constructor(filePath, onCompletion) {
        console.log('[MultiFileWriter] Constructor called');
        console.log('[MultiFileWriter] File path:', filePath);
        this.#callback = onCompletion;
        this.#filePath = filePath;
    }

    #areAllWriteComplete() {
        console.log('[MultiFileWriter] Checking if all writers completed');
        console.log('[MultiFileWriter] Total writers:', this.#fileWriter.length);

        let completedCount = 0;
        for (let writer of this.#fileWriter) {
            if (writer.isCompleted) {
                completedCount++;
            } else {
                console.log('[MultiFileWriter] Writer not yet completed, returning');
                return;
            }
        }

        console.log('[MultiFileWriter] All', completedCount, 'writers completed!');

        if (this.#callback) {
            console.log('[MultiFileWriter] Calling completion callback');
            this.#callback();
        } else {
            console.warn('[MultiFileWriter] No callback defined');
        }
    }

    /**
     *
     * @param {T} fileWriter
     * @param {ConstructorParameters<T>} constructorParams
     */
    addFileWriter(fileWriter, constructorParams) {
        console.log('[MultiFileWriter] Adding file writer');
        console.log('[MultiFileWriter] Writer class:', fileWriter.name);

        constructorParams[1].onCompletion = this.#areAllWriteComplete.bind(this);
        const writerInstance = new fileWriter(...constructorParams);
        this.#fileWriter.push(writerInstance);

        console.log('[MultiFileWriter] File writer added. Total writers:', this.#fileWriter.length);
    }


    /**
     *
     * @param {AbstractFileWriter} fileWriter
     */
    removeFileWriter(fileWriter) {
        console.log('[MultiFileWriter] Removing file writer');
        const beforeCount = this.#fileWriter.length;
        this.#fileWriter = this.#fileWriter.filter((element) => element !== fileWriter);
        console.log('[MultiFileWriter] Writers removed:', beforeCount - this.#fileWriter.length);
    }


    /**
     * @param {Blob} blob
     */
    write(blob) {
        console.log('[MultiFileWriter] Writing blob to', this.#fileWriter.length, 'writers. Size:', blob.size, 'bytes');
        this.#fileWriter.forEach(writer => writer.write(blob));
    }

    async writeAllChunks() {
        console.log('[MultiFileWriter] writeAllChunks called for', this.#fileWriter.length, 'writers');
        const promiseArray = [];
        this.#fileWriter.forEach(writer => {
            promiseArray.push(writer.writeAllChunks());
        });
        await Promise.all(promiseArray);
        console.log('[MultiFileWriter] All writers completed writeAllChunks');
    }

    setWriteComplete() {
        console.log('[MultiFileWriter] setWriteComplete called for', this.#fileWriter.length, 'writers');
        this.#fileWriter.forEach(writer => writer.setWriteComplete());
    }
}

module.exports = MultiFileWriter;