const fs = require('fs');
const logger = require('electron-log');
const path = require('path');
const console = logger;

class FileWriter {

    /**
     * @type {string}
     */
    #filePath

    /**
     * @type {fs.WriteStream}
     */
    #fileStream

    /**
     * @type {Array<Blob>}
     */
    #arrayOfBlobToWrite

    /**
     * @type {boolean}
     */
    #writeComplete


    /**
     * @type {{ onCompletion?: (string) => void, intervalInSec: number }}
     */
    #config

    /**
     * @type {NodeJS.Timeout}
     */
    #interval

    /**
     * @type {boolean}
     */
    #currentlyProcessing

    /**
     * @type {boolean}
     */
    #isCompleted

    /**
     *
     * @param {string} fileName
     * @param {{ onCompletion?: (string) => void }} config
     */
    constructor(filePath, config ) {
        console.log('[FileWriter] Constructor called');
        console.log('[FileWriter] File path:', filePath);
        console.log('[FileWriter] Config:', config);

        this.#currentlyProcessing = false;
        this.#writeComplete = false;
        this.#isCompleted = false;
        this.#filePath = filePath;
        this.#arrayOfBlobToWrite = [];

        const directory = path.join(filePath, '../');
        if (!fs.existsSync(directory)) {
            console.log('[FileWriter] Creating directory:', directory);
            fs.mkdirSync(directory, { recursive: true });
        }

        console.log('[FileWriter] Creating write stream');
        this.#fileStream = fs.createWriteStream(this.#filePath);

        this.#fileStream.on('error', (err) => {
            console.error('[FileWriter] File stream error:', err);
        });

        this.#fileStream.on('finish', () => {
            console.log('[FileWriter] File stream finished');
        });

        this.#config = {...config, intervalInSec: 1};
        this.#startWriter(this.#config.intervalInSec);

        console.log('[FileWriter] Initialized with write interval:', this.#config.intervalInSec, 'ms');
    }

    get isCompleted() {
        return this.#isCompleted;
    }
    
    /**
     *
     * @param {Blob} blob
     */
    write(blob) {
        if (this.#writeComplete) {
            console.error('[FileWriter] Attempted to write after completion signal');
            throw new Error('Writing not allowed after complete signal is given');
        }
        this.#arrayOfBlobToWrite.push(blob);
        console.log('[FileWriter] Blob queued. Queue size:', this.#arrayOfBlobToWrite.length, 'Blob size:', blob.size, 'bytes');
    }

    /**
     * 
     * @param {number} intervalInSec
     */
    #startWriter(intervalInSec) {
        console.log('[FileWriter] Starting background writer interval');
        this.#interval = setInterval(async () => {
            try {
                if (this.#currentlyProcessing) {
                    return false;
                }
                this.#currentlyProcessing = true;

                const queueSize = this.#arrayOfBlobToWrite.length;
                const toWrite = this.#arrayOfBlobToWrite.shift();

                if (toWrite) {
                    console.log('[FileWriter] Processing blob from queue. Remaining:', queueSize - 1);
                    await this.#writeToFile(toWrite);
                }

                if (!toWrite && this.#writeComplete) {
                    console.log('[FileWriter] Queue empty and write complete signal received');
                    clearInterval(this.#interval);
                    console.log('[FileWriter] Closing file stream');
                    this.#fileStream.end();
                    this.#isCompleted = true;
                    console.log('[FileWriter] File writing completed for:', this.#filePath);

                    if (this.#config?.onCompletion) {
                        console.log('[FileWriter] Calling onCompletion callback');
                        this.#config.onCompletion(this.#filePath);
                    }
                }
            } catch (error) {
                console.error('[FileWriter] Error in writer interval:', error);
            } finally {
                this.#currentlyProcessing = false;
            }
        }, intervalInSec);
    }

    /**
     *
     * @param {Blob} data
     */
    async #writeToFile(data) {
        const arrayBuffer = await data.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);
        console.log('[FileWriter] Writing', buffer.length, 'bytes to file');
        this.#fileStream.write(buffer);
    }

    setWriteComplete() {
        console.log('[FileWriter] setWriteComplete called. Queue size:', this.#arrayOfBlobToWrite.length);
        this.#writeComplete = true;
    }

    async writeAllChunks() {
        console.log('[FileWriter] writeAllChunks called - forcing immediate write of remaining chunks');

        // Clear the interval to stop background writing
        clearInterval(this.#interval);
        console.log('[FileWriter] Background writer interval cleared');

        // Wait for any in-progress write to complete
        while (this.#currentlyProcessing) {
            console.log('[FileWriter] Waiting for current write to complete...');
            await new Promise(resolve => setTimeout(resolve, 100));
        }

        // Write all remaining chunks synchronously
        const remainingChunks = this.#arrayOfBlobToWrite.length;
        console.log('[FileWriter] Writing', remainingChunks, 'remaining chunks immediately');

        let writtenCount = 0;
        while(true) {
            try {
                const toWrite = this.#arrayOfBlobToWrite.shift();
                if (!toWrite) {
                    break;
                }
                await this.#writeToFile(toWrite);
                writtenCount++;
            } catch (error) {
                console.error('[FileWriter] Error writing chunk:', error);
            }
        }

        console.log('[FileWriter] Written', writtenCount, 'of', remainingChunks, 'chunks');

        // Close the stream and mark as completed
        console.log('[FileWriter] Closing file stream');
        this.#fileStream.end();
        this.#isCompleted = true;
        console.log('[FileWriter] All chunks written and file completed:', this.#filePath);
    }
}

module.exports = FileWriter